def plot_achieved_gdpt_vs_latency(
    experiment_family, title_addendum, experiment_date,
    ssird_achieved_gdpt_gbps_list, xpass_achieved_gdpt_gbps_list, dctcp_achieved_gdpt_gbps_list,
    ssird_fct_s_list_list, xpass_fct_s_list_list, dctcp_fct_s_list_list,
    x_lim=None, y_lim=None
):

    print([len(fct_list) for fct_list in ssird_fct_s_list_list])
    print([len(fct_list) for fct_list in xpass_fct_s_list_list])
    print([len(fct_list) for fct_list in dctcp_fct_s_list_list])

    plt.figure(figsize=(10, 6))
    plt.xlabel(f'Acheived Goodput (Gbps)')
    plt.ylabel('Latency (us)')
    plt.title(f'Achieved Goodput vs Latency\n{experiment_family}{title_addendum}\n{experiment_date}')

    ssird_fct_s_90p = [np.percentile(np.array(fct_s_list), 90) for fct_s_list in ssird_fct_s_list_list]
    xpass_fct_s_90p = [np.percentile(np.array(fct_s_list), 90) for fct_s_list in xpass_fct_s_list_list]
    dctcp_fct_s_90p = [np.percentile(np.array(fct_s_list), 90) for fct_s_list in dctcp_fct_s_list_list]

    ssird_fct_us = [x*1000*1000 for x in ssird_fct_s_90p]
    xpass_fct_us = [x*1000*1000 for x in xpass_fct_s_90p]
    dctcp_fct_us = [x*1000*1000 for x in dctcp_fct_s_90p]
    # ssird_fct_ms = ssird_fct_s_90p
    # xpass_fct_ms = xpass_fct_s_90p
    # dctcp_fct_ms = dctcp_fct_s_90p

    print(ssird_fct_s_90p)
    print(xpass_fct_s_90p)
    print(dctcp_fct_s_90p)

    plt.plot(ssird_achieved_gdpt_gbps_list, ssird_fct_us, label="SSIRD", linestyle='-', marker='^', color=SSIRD_PLOT_COLOUR, markersize=8)
    plt.plot(xpass_achieved_gdpt_gbps_list, xpass_fct_us, label="ExpressPass", linestyle='-', marker='s', color=XPASS_PLOT_COLOUR, markersize=7)
    plt.plot(dctcp_achieved_gdpt_gbps_list, dctcp_fct_us, label="DCTCP", linestyle='-', marker='o', color=DCTCP_PLOT_COLOUR, markersize=7)

    plt.legend()

    ax = plt.gca()
    ax.grid(True, which='both')

    if (x_lim is not None):
        ax.set_xlim(x_lim)
    if (y_lim is not None):
        ax.set_ylim(y_lim)


    Path(PATH_TO_THRPT_VS_LATENCY).mkdir(parents=True, exist_ok=True)
    filename = f"allproto_achieved_gdpt_vs_latency_{experiment_family}{title_addendum}_{experiment_date}.png"
    plt.savefig(f"{PATH_TO_THRPT_VS_LATENCY}{filename}")
    plt.close()

